/**
 * Focalis — site config (generated by /admin/config — no developer needed)
 * Source: site.config.json (public values only — the private forwardTo never leaves the server)
 * Generated: {datetime.now(timezone.utc).isoformat()}
 */
window.FOCALIS_CONFIG = {
  "site": {
    "domain": "focalis.cc",
    "title": "Focalis",
    "tagline": "Technology that gives time back"
  },
  "company": {
    "legalName": "Focalis S.A.S.",
    "location": "Bogotá, Colombia",
    "fullAddress": "Bogotá, D.C., Colombia",
    "founded": "2019"
  },
  "contact": {
    "primaryEmail": "hello@focalis.cc",
    "supportEmail": "contact@focalis.cc",
    "legalEmail": "contact@focalis.cc",
    "responseTime": "within 24 hours on business days (Mon–Fri, Bogotá UTC-5)"
  }
};
(function(){
  if (typeof document === 'undefined') return;
  function get(path){ return path.split('.').reduce((o,k)=>o&&o[k], window.FOCALIS_CONFIG); }
  function apply(){
    document.querySelectorAll('[data-config]').forEach(el=>{
      const v=get(el.getAttribute('data-config')); if(v){
        if(el.tagName==='A' && el.getAttribute('href')?.startsWith('mailto:')) el.href='mailto:'+v;
        el.textContent=v;
      }
    });
    document.querySelectorAll('[data-config-href]').forEach(el=>{ const v=get(el.getAttribute('data-config-href')); if(v) el.href='mailto:'+v; });
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded', apply); else apply();
})();
